"""Bind generated bytes into a fresh runtime manifest; preserve structural source."""
import copy
import json
import re
import shutil
from pathlib import Path
import generated_inputs as generated
from execution_evidence import digest


def pin(path):
    path = Path(path).resolve(strict=True)
    return {'path': str(path), 'sha256': digest(path)}


def write(path, value):
    with path.open('x') as stream:
        json.dump(value, stream, indent=2, sort_keys=True, allow_nan=False)
        stream.write('\n')


def commands(cases, old_lane, new_lane):
    result = copy.deepcopy(cases)
    for entry in result.values():
        argv = entry['command']
        if argv.count('--manifest') != 1:
            raise ValueError('generated case requires one explicit lane-manifest argument')
        index = argv.index('--manifest') + 1
        if index >= len(argv) or Path(argv[index]).resolve() != Path(old_lane).resolve():
            raise ValueError('case command differs from frozen lane manifest')
        argv[index] = str(Path(new_lane).resolve())
    return result


def prepare(parent_path, manifest, directory):
    parent_path = Path(parent_path).resolve(strict=True)
    if json.loads(parent_path.read_text()) != manifest or 'generated_bindings' in manifest:
        raise ValueError('runtime preparation requires the unchanged structural manifest')
    recipes = generated.structural_context(manifest)
    if recipes is None:
        raise ValueError('no generated structural inputs')
    parent_pin = pin(parent_path)
    old_lane = manifest['lane_manifest']
    generated.pin(old_lane)
    lanes = json.loads(Path(old_lane['path']).read_text())
    prompts = lanes['lanes'][manifest['lane']]['prompt_sets']
    referenced = [value['generated_input'] for value in prompts.values() if set(value) == {'generated_input'}]
    if len(referenced) != len(set(referenced)) or set(referenced) != set(recipes):
        raise ValueError('runtime recipes must match every unique generated prompt reference')
    directory = Path(directory).resolve()
    directory.mkdir(parents=True, exist_ok=False)
    bindings = {}
    extra = [parent_pin]
    for entry in manifest['generated_inputs']:
        recipe = entry['recipe']
        root = directory / recipe['id']
        binding = generated.materialize(recipe, manifest['build_receipt']['path'], manifest['candidate_sha'],
                                        root, entry['structural']['recipe_sha256'])
        bindings[recipe['id']] = pin(root / 'binding.json')
        extra.append(bindings[recipe['id']])
        for attempt in ('actual', 'rederived'):
            extra.extend(binding[attempt].values())
            extra.append(pin(root / attempt / 'command.json'))
            log = root / attempt / 'generator.log'
            if log.is_file():
                extra.append(pin(log))
    target = directory / 'datasets'
    target.mkdir()
    for name, source in list(prompts.items()):
        if not re.fullmatch(r'[A-Za-z][A-Za-z0-9_-]{0,63}', name):
            raise ValueError('unsafe generated prompt slot')
        if set(source) == {'generated_input'}:
            binding = json.loads(Path(bindings[source['generated_input']]['path']).read_text())
            source = binding['actual']['prompts.jsonl']
        generated.pin(source)
        destination = target / (name + '.jsonl')
        shutil.copyfile(source['path'], destination)
        prompts[name] = pin(destination)
        if prompts[name]['sha256'] != source['sha256']:
            raise ValueError('runtime prompt copy differs from bound input')
        extra.append(prompts[name])
    runtime_lane = directory / 'lane.json'
    write(runtime_lane, lanes)
    runtime = copy.deepcopy(manifest)
    runtime.update(parent_structural_manifest=parent_pin, generated_bindings=bindings, lane_manifest=pin(runtime_lane))
    runtime['cases'] = commands(manifest['cases'], old_lane['path'], runtime_lane)
    runtime['inputs'] = manifest.get('inputs', []) + extra + [pin(runtime_lane)]
    verify(runtime)
    result = directory / 'case.json'
    write(result, runtime)
    return result, runtime


def verify(manifest):
    recipes = generated.structural_context(manifest)
    if recipes is None or set(manifest.get('generated_bindings', {})) != set(recipes):
        raise ValueError('runtime requires every generated binding')
    parent = manifest['parent_structural_manifest']
    generated.pin(parent)
    original = json.loads(Path(parent['path']).read_text())
    if 'generated_bindings' in original:
        raise ValueError('runtime parent must be structural-only')
    generated.structural_context(original)
    changed = {'parent_structural_manifest', 'generated_bindings', 'lane_manifest', 'cases', 'inputs'}
    if ({key: value for key, value in manifest.items() if key not in changed}
            != {key: value for key, value in original.items() if key not in changed}):
        raise ValueError('runtime changed frozen structural identity/configuration')
    generated.pin(manifest['lane_manifest'])
    root = Path(manifest['lane_manifest']['path']).resolve().parent
    lanes = json.loads(Path(manifest['lane_manifest']['path']).read_text())
    expected_lanes = json.loads(Path(original['lane_manifest']['path']).read_text())
    generated.pin(original['lane_manifest'])
    outputs = {}
    required = [parent, manifest['lane_manifest']]
    for name, value in manifest['generated_bindings'].items():
        if Path(value['path']).resolve() != root / name / 'binding.json':
            raise ValueError('runtime binding must belong to its fresh input directory')
        generated.pin(value)
        binding = json.loads(Path(value['path']).read_text())
        recipe = recipes[name]
        if (binding.get('stage') != 'runtime-bound' or binding.get('candidate_sha') != manifest['candidate_sha']
                or binding.get('recipe_id') != name or binding.get('recipe_sha256') != generated.contract_hash(recipe)
                or binding.get('seed') != recipe['seed']):
            raise ValueError('runtime binding differs from structural source/config/seed')
        for attempt in ('actual', 'rederived'):
            command = root / name / attempt / 'command.json'
            if json.loads(command.read_text()) != generated.argv(recipe, command.parent):
                raise ValueError('runtime generator command/config/seed differs from frozen recipe')
            required.extend([pin(command), pin(command.parent / 'generator.log')])
            if set(binding[attempt]) != {'prompts.jsonl', 'selection-report.json'}:
                raise ValueError('runtime output registry mismatch')
            for filename, item in binding[attempt].items():
                if Path(item['path']).resolve() != root / name / attempt / filename:
                    raise ValueError('runtime output outside owned generation directory')
                generated.pin(item)
                required.append(item)
        if binding['actual']['prompts.jsonl']['sha256'] != binding['rederived']['prompts.jsonl']['sha256']:
            raise ValueError('runtime re-derivation does not match')
        outputs[name] = binding['actual']['prompts.jsonl']
        required.append(value)
    prompts = expected_lanes['lanes'][manifest['lane']]['prompt_sets']
    actual_prompts = lanes['lanes'][manifest['lane']]['prompt_sets']
    if set(prompts) != set(actual_prompts):
        raise ValueError('runtime prompt slots changed')
    for name, old in list(prompts.items()):
        if not re.fullmatch(r'[A-Za-z][A-Za-z0-9_-]{0,63}', name):
            raise ValueError('unsafe runtime prompt slot')
        expected = outputs[old['generated_input']] if set(old) == {'generated_input'} else old
        generated.pin(expected)
        item = actual_prompts[name]
        if (Path(item['path']).resolve() != root / 'datasets' / (name + '.jsonl')
                or item['sha256'] != expected['sha256']):
            raise ValueError('runtime prompt copy differs from generated/concrete input')
        generated.pin(item)
        prompts[name] = item
        required.append(item)
    if lanes != expected_lanes or manifest['cases'] != commands(original['cases'], original['lane_manifest']['path'], manifest['lane_manifest']['path']):
        raise ValueError('runtime changed server configuration or measured command')
    frozen = {str(Path(item['path']).resolve()): item['sha256'] for item in manifest['inputs']}
    for item in original.get('inputs', []) + required:
        if frozen.get(str(Path(item['path']).resolve())) != item['sha256']:
            raise ValueError('runtime omitted frozen/generated provenance inputs')
        generated.pin(item)
